import heapq
from collections import Counter

def get_minimum_moves(capacity, cluster_size):
    k = cluster_size
    cnt = Counter(capacity)
    suffix = 0          # sum of remainders of values > current
    kept = []           # min-heap of remainders we decide to keep
    for v in sorted(cnt, reverse=True):
        r = cnt[v] % k
        if r == 0:
            continue
        suffix += r
        heapq.heappush(kept, r)
        if len(kept) * k > suffix:
            heapq.heappop(kept)
    return sum(cnt[v] % k for v in cnt) - sum(kept)
